CREATE TABLE IF NOT EXISTS "public"."aggregates_events"
(
    "id"                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "database"          character varying(255) NOT NULL,
    "aggregate_name"    character varying(255) NOT NULL,
    "aggregate_id"      character varying(255) NOT NULL,
    "sequence_number"   integer NOT NULL,
    "data"              JSONB NOT NULL,
    "created_at"        timestamptz NOT NULL DEFAULT NOW()
) WITH (oids = false);

CREATE UNIQUE INDEX "aggregates_events_idx" 
    ON "public"."aggregates_events" ("database", "aggregate_name", "aggregate_id", "sequence_number");
